#!/usr/bin/env python3
"""Patches the Android project generated by `flutter create` for WPDF."""
import glob
import os
import re
import shutil
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
ANDROID = os.path.join(ROOT, "android")
APP = os.path.join(ANDROID, "app")
MAIN = os.path.join(APP, "src", "main")


def read(p):
    with open(p, encoding="utf-8") as f:
        return f.read()


def write(p, s):
    with open(p, "w", encoding="utf-8") as f:
        f.write(s)


def patch_manifest():
    p = os.path.join(MAIN, "AndroidManifest.xml")
    s = read(p)

    perms = [
        "android.permission.READ_EXTERNAL_STORAGE",
        "android.permission.WRITE_EXTERNAL_STORAGE",
        "android.permission.INTERNET",
    ]
    add = ""
    for perm in perms:
        if perm not in s:
            add += f'    <uses-permission android:name="{perm}"/>\n'
    s = s.replace("<application", add + "    <application", 1)

    s = re.sub(r'android:label="[^"]*"', 'android:label="WPDF"', s, count=1)
    if "android:requestLegacyExternalStorage" not in s:
        s = s.replace("<application", '<application android:requestLegacyExternalStorage="true"', 1)

    # Open PDF files from other apps / file managers.
    intent = """
            <intent-filter>
                <action android:name="android.intent.action.VIEW"/>
                <category android:name="android.intent.category.DEFAULT"/>
                <category android:name="android.intent.category.BROWSABLE"/>
                <data android:mimeType="application/pdf"/>
                <data android:scheme="content"/>
                <data android:scheme="file"/>
            </intent-filter>
"""
    if "application/pdf" not in s:
        s = s.replace("</activity>", intent + "        </activity>", 1)
    write(p, s)


def patch_gradle():
    done = False
    for name in ("build.gradle.kts", "build.gradle"):
        p = os.path.join(APP, name)
        if not os.path.exists(p):
            continue
        s = read(p)
        s2 = re.sub(r"minSdk\s*=\s*flutter\.minSdkVersion", "minSdk = 24", s)
        s2 = re.sub(r"minSdkVersion\s*=?\s*flutter\.minSdkVersion", "minSdkVersion 24", s2)
        s2 = re.sub(r"minSdk\s*=\s*\d+", "minSdk = 24", s2) if name.endswith(".kts") else s2
        write(p, s2)
        done = True
        print("patched", name)
    if not done:
        sys.exit("no app gradle file found")


def copy_icons():
    src = os.path.join(ROOT, "tools", "res")
    dst = os.path.join(MAIN, "res")
    for path in glob.glob(os.path.join(src, "**", "*"), recursive=True):
        if os.path.isdir(path):
            continue
        rel = os.path.relpath(path, src)
        out = os.path.join(dst, rel)
        os.makedirs(os.path.dirname(out), exist_ok=True)
        shutil.copy(path, out)
    print("icons copied")


if __name__ == "__main__":
    if not os.path.isdir(ANDROID):
        sys.exit("android/ not found - run flutter create first")
    patch_manifest()
    patch_gradle()
    copy_icons()
    print("android patched")
